import { Component, input } from '@angular/core';
import { RouterLink } from '@angular/router';
import { TablerIconComponent } from '@tabler/icons-angular';
import { NzBreadCrumbModule } from 'ng-zorro-antd/breadcrumb';

export interface HrmCrumb {
  title: string;
  link?: string;
  /** Icon Tabler tùy chọn đứng trước nhãn (object mode). */
  icon?: unknown;
}

/** hrm-breadcrumb — config-driven, bọc nz-breadcrumb. link → routerLink, icon → tabler-icon, separator tùy biến. */
@Component({
  selector: 'hrm-breadcrumb',
  imports: [NzBreadCrumbModule, RouterLink, TablerIconComponent],
  template: `
    <nz-breadcrumb [nzSeparator]="separator() || '/'">
      @for (c of items(); track c.title) {
        <nz-breadcrumb-item>
          @if (c.link) {
            <a [routerLink]="c.link">
              @if (c.icon) { <tabler-icon class="hrm-bc-ic" [icon]="$any(c.icon)" [size]="16" /> }{{ c.title }}
            </a>
          } @else {
            @if (c.icon) { <tabler-icon class="hrm-bc-ic" [icon]="$any(c.icon)" [size]="16" /> }{{ c.title }}
          }
        </nz-breadcrumb-item>
      }
    </nz-breadcrumb>
  `,
  styles: [`
.hrm-bc-ic { display: inline-flex; vertical-align: text-bottom; margin-right: 4px; }
  `],
  host: { class: 'hrm-breadcrumb' },
})
export class HrmBreadcrumb {
  readonly items = input<HrmCrumb[]>([]);
  /** Ký tự phân cách giữa các cấp; để trống dùng mặc định "/". */
  readonly separator = input<string>('');
}
